// Editable local SBAR handoff. Workflow values refresh until a user edits a field.
const FIELDS={situation:[["hospital","Hospital"],["reasonForConsult","Reason for consultation"],["presentingSymptoms","Presenting symptoms"],["lastKnownWell","Last known well"]],background:[["medicalHistory","Relevant medical history"],["anticoagulants","Anticoagulants / antiplatelets"],["baselineFunction","Baseline functional status"],["allergies","Relevant allergies"]],assessment:[["nihss","NIHSS"],["neurologicalExam","Neurological examination"],["ncctFindings","Noncontrast CT head"],["ctaFindings","CTA head/neck"],["lvoStatus","LVO assessment"],["clinicalImpression","Clinical impression"]],recommendation:[["thrombolysisDecision","IV thrombolysis decision"],["thrombectomyEvaluation","Thrombectomy evaluation"],["additionalImaging","Further imaging"],["transferPlan","Transfer / disposition"],["monitoringPlan","Monitoring / follow-up"],["communication","Communication with bedside team"]]};
const TITLES={situation:"S — Situation",background:"B — Background",assessment:"A — Assessment",recommendation:"R — Recommendation"};
const clean=value=>value==null?"":typeof value==="object"?"":String(value).trim();
export function generateSBAR(data={}){return Object.entries(FIELDS).map(([section,fields])=>{const lines=fields.map(([key,label])=>{const value=clean(data[key]);return value?`${label}: ${value}`:"";}).filter(Boolean);return lines.length?[TITLES[section],...lines].join("\n"):"";}).filter(Boolean).join("\n\n");}
export function mountSBAR(container,encounter={}){if(!container)throw new Error("SBAR container not found.");let data={},edited=new Set();const mergeWorkflow=next=>{for(const fields of Object.values(FIELDS))for(const [key] of fields){const value=clean(next[key]);if(!edited.has(key))data[key]=value;}};mergeWorkflow(encounter);const form=document.createElement("div");form.className="axon-sbar-form";container.replaceChildren();container.append(form);for(const [section,fields] of Object.entries(FIELDS)){const fieldset=document.createElement("fieldset");fieldset.className="axon-sbar-section";const legend=document.createElement("legend");legend.textContent=TITLES[section];fieldset.append(legend);for(const [key,labelText] of fields){const label=document.createElement("label");label.className="axon-sbar-field";const title=document.createElement("span");title.textContent=labelText;const input=document.createElement("textarea");input.rows=2;input.value=data[key]||"";input.dataset.sbarField=key;input.addEventListener("input",()=>{edited.add(key);data[key]=input.value;updatePreview();});label.append(title,input);fieldset.append(label);}form.append(fieldset);}const previewHeading=document.createElement("h3");previewHeading.textContent="SBAR preview";const preview=document.createElement("pre");preview.className="axon-sbar-preview";const feedback=document.createElement("p");feedback.setAttribute("role","status");const copy=document.createElement("button");copy.type="button";copy.textContent="Copy SBAR";copy.addEventListener("click",async()=>{try{await navigator.clipboard.writeText(generateSBAR(data));feedback.textContent="SBAR copied to clipboard.";}catch{feedback.textContent="Clipboard unavailable. Select and copy the preview.";}});container.append(previewHeading,preview,copy,feedback);function updatePreview(){preview.textContent=generateSBAR(data)||"No SBAR details documented yet.";}updatePreview();return {updateEncounter(next={}){mergeWorkflow(next);for(const [key,value] of Object.entries(data)){const input=form.querySelector(`[data-sbar-field="${key}"]`);if(input&&!edited.has(key))input.value=value;}updatePreview();},getText:()=>generateSBAR(data)};}
